setItem.value:
function (key) {
    var storageType =
      this === window.localStorage
        ? "localStorage"
        : this === window.sessionStorage
        ? "sessionStorage"
        : "unknown";

    post("storage-event", { storageType: storageType, key: String(key) });
    return originalSetItem.apply(this, arguments);
  }

